/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveSwingLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "In jazz the ride cymbal is the time: \"ding, ding-a-ding\" carries the whole band, the hi-hat foot locks 2 and 4, and the snare is free to talk. This is the groove of small-group jazz and big-band swing.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Ride on every quarter, plus the last triplet note after 2 and after 4 — \"ding, ding-a ding, ding-a\". The left foot closes the hi-hat on 2 and 4 with a crisp \"chick\", the kick feathers soft quarters you feel more than hear.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 1 is ride, hat and feathered kick only — get it light and steady first; line 6 adds one real kick on the \"let\" of 4 as a pickup into the next bar. Lines 2, 3, 5 and 7 add single snare comments; keep them conversational, not a backbeat. Line 8 accents the ride on 1 and 3 and answers on the \"a\" of 2 and 4.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Miles Davis \"So What\" with Jimmy Cobb, Art Blakey and the Jazz Messengers, Count Basie with Sonny Payne, Dave Brubeck \"Take Five\" in its own 5/4 way — the ride pattern is the same language.",
  ),
];
